// frontend/src/pages/AdminProducts.js

import React, { useEffect, useState } from "react";
import {
  getProducts,
  deleteProduct,
  updateProduct,
  createProduct
} from "../services/api";

export default function AdminProducts() {
  const [products, setProducts] = useState([]);

  // ─── Încarcă produsele la montare ─────────────────────────────
  const fetchProducts = async () => {
    try {
      const res = await getProducts();
      setProducts(res.data);
    } catch (err) {
      console.error("Eroare la încărcarea produselor:", err);
    }
  };

  useEffect(() => {
    fetchProducts();
  }, []);

  // ─── Șterge produs ─────────────────────────────────────────────
  const handleDelete = async (id) => {
    if (!window.confirm("Sigur vrei să ștergi acest produs?")) return;
    try {
      await deleteProduct(id);
      fetchProducts();
    } catch (err) {
      console.error("Eroare la ștergere produs:", err);
    }
  };

  return (
    <div style={{ padding: 20, maxWidth: 800, margin: "0 auto" }}>
      <h2 style={{ textAlign: "center", marginBottom: 20 }}>Administrare Produse</h2>

      <table style={{ width: "100%", borderCollapse: "collapse" }}>
        <thead>
          <tr>
            <th style={{ borderBottom: "1px solid #ccc", padding: 8 }}>Imagine</th>
            <th style={{ borderBottom: "1px solid #ccc", padding: 8 }}>Nume</th>
            <th style={{ borderBottom: "1px solid #ccc", padding: 8 }}>Descriere</th>
            <th style={{ borderBottom: "1px solid #ccc", padding: 8 }}>Preț</th>
            <th style={{ borderBottom: "1px solid #ccc", padding: 8 }}>Acțiuni</th>
          </tr>
        </thead>

        <tbody>
          {products.map((p) => (
            <tr key={p.ProductId} style={{ borderTop: "1px solid #eee" }}>
              {/* ─── Coloana Imagine ────────────────────────────────────────── */}
              <td style={{ padding: 8, textAlign: "center" }}>
                {p.ImageUrl ? (
                  <img
                    src={p.ImageUrl}
                    alt={p.Name}
                    style={{ height: 50, objectFit: "cover" }}
                  />
                ) : (
                  <span>(fără poză)</span>
                )}
              </td>

              {/* ─── Coloana Nume ──────────────────────────────────────────── */}
              <td style={{ padding: 8 }}>{p.Name}</td>

              {/* ─── Coloana Descriere ─────────────────────────────────────── */}
              <td style={{ padding: 8, fontSize: "0.9em" }}>{p.Description}</td>

              {/* ─── Coloana Preț ──────────────────────────────────────────── */}
              <td style={{ padding: 8, textAlign: "right" }}>{p.Price} lei</td>

              {/* ─── Coloana Acțiuni ───────────────────────────────────────── */}
              <td style={{ padding: 8, textAlign: "center" }}>
                <button
                  onClick={() => handleDelete(p.ProductId)}
                  style={{
                    padding: "4px 8px",
                    backgroundColor: "#e63946",
                    color: "#fff",
                    border: "none",
                    borderRadius: 4,
                    cursor: "pointer"
                  }}
                >
                  Șterge
                </button>
              </td>
            </tr>
          ))}
        </tbody>
      </table>
    </div>
  );
}
